"""E77 verdict (lines registered in docs/EVIDENCE.md): python experiments/robot/analyse_e77.py results/e77 -> results/e77/REPORT_E77.md"""
import json, sys, numpy as np
root = sys.argv[1]; L = lambda s: json.load(open(f"{root}/ladder/N_s{s}.json")); P = lambda s: json.load(open(f"{root}/slices/N_s{s}.json")); S = range(5)
N, SL = [L(s) for s in S], [P(s) for s in S]; J = [json.load(open(f"results/e76/ladder/J_s{s}.json")) for s in S]
f = lambda x, n=2: f"{x:.{n}f}"
md = ["# E77 report (generated by experiments/robot/analyse_e77.py)", "", "## Per seed", "",
      "| Seed | cam acc slice1 / slices2-4 | layout R2 slice4 / all | progress R2 slice3 / all | rung-1 d / gap | cam acc V1 / Q1 | viewpoint ratio | rung-2 d / gap | rung-3 d / gap |", "|---|---|---|---|---|---|---|---|---|"]
for s in S:
    a, b = N[s], SL[s]
    md.append(f"| {s} | {f(b['camera_acc']['camera'])} / {f(b['camera_acc']['slices 2-4'])} | {f(b['layout_R2']['layout'])} / {f(b['layout_R2']['all'])} | {f(b['progress_R2']['progress'])} / {f(b['progress_R2']['all'])} | {a['rung1']['d']} / {f(a['rung1']['gap_ratio'])} | {f(a['camera_acc']['from_V1'])} / {f(a['camera_acc']['from_Q1'])} | {f(a['viewpoint_ratio_V1_over_Q1'])} | {a['rung2']['d']} / {f(a['rung2']['gap_ratio'])} | {a['rung3']['d']} / {f(a['rung3']['gap_ratio'])} |")
nA = sum(b["camera_acc"]["camera"] >= 0.9 and b["camera_acc"]["slices 2-4"] <= 0.6 for b in SL)
nB = sum(a["rung1"]["gap_ratio"] >= 2 and a["camera_acc"]["from_V1"] >= 0.9 for a in N)
nC = sum(b["layout_R2"]["layout"] >= 0.5 for b in SL)
rn, rj = np.mean([a["viewpoint_ratio_V1_over_Q1"] for a in N]), np.mean([a["viewpoint_ratio_V1_over_Q1"] for a in J]); dD = rn - rj
ok = [nA >= 3, nB >= 3, nC >= 3, dD >= 1.0]
md += ["", "## Registered lines", "",
 f"- (a) slice 1 isolates the camera (acc >= 0.9 from slice 1, <= 0.6 from slices 2-4), >= 3 of 5 seeds: observed {nA} of 5 (slice 1: {', '.join(f(b['camera_acc']['camera']) for b in SL)}; slices 2-4: {', '.join(f(b['camera_acc']['slices 2-4']) for b in SL)}): **{'met' if ok[0] else 'NOT met, short by %d seed(s)' % (3 - nA)}**",
 f"- (b) rung-1 gap >= 2 and camera acc from V1 >= 0.9, >= 3 of 5 seeds: observed {nB} of 5 (gaps {', '.join(f(a['rung1']['gap_ratio']) for a in N)}; acc V1 {', '.join(f(a['camera_acc']['from_V1']) for a in N)}): **{'met' if ok[1] else 'NOT met, short by %d seed(s)' % (3 - nB)}**",
 f"- (c) layout R2 from slice 4 >= 0.5, >= 3 of 5 seeds: observed {nC} of 5 ({', '.join(f(b['layout_R2']['layout']) for b in SL)}): **{'met' if ok[2] else 'NOT met, short by %d seed(s); best %.2f, required 0.5' % (3 - nC, max(b['layout_R2']['layout'] for b in SL))}**",
 f"- (d) viewpoint ratio N minus J (seed means) >= 1.0: N {f(rn)}, J {f(rj)}, difference {f(dD)}: **{'met' if ok[3] else 'NOT met, short by %.2f' % (1.0 - dD)}**",
 f"- E77 verdict: **{'CONFIRMED' if all(ok) else 'REFUTED'}**"]
open(f"{root}/REPORT_E77.md", "w").write("\n".join(md) + "\n"); print("\n".join(md))
